def fix_romanian(text: str) -> str:
    """
    Replace cedilla-based Romanian letters (ş, Ş, ţ, Ţ) with comma-below ones (ș, Ș, ț, Ț).
    """
    replacements = {
        'ş': 'ș',
        'Ş': 'Ș',
        'ţ': 'ț',
        'Ţ': 'Ț'
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return text
